import fs from 'node:fs';import assert from 'node:assert/strict';import YAML from 'yaml';import {execFileSync} from 'node:child_process';import {createHash} from 'node:crypto';
const file='data/benchmarks/fast-pull-request-retained-jobs.json';
const old=YAML.parse(execFileSync('git',['show','5e6037196159d1a83f3bbe23f2c404dbdae1105e^:.github/workflows/security.yml'],{encoding:'utf8'})).jobs.codeql;
const current=YAML.parse(fs.readFileSync('.github/workflows/security.yml','utf8')).jobs.codeql;
const payload=job=>({steps:job.steps,uses:job.uses,with:job.with,strategy:job.strategy});
const normalized=structuredClone(current), observer=normalized.steps.filter(step=>step.name==='Observe included Rust string payloads');
assert.equal(observer.length,1);
assert.equal(observer[0].if,"${{ github.job == 'codeql-readonly' && matrix.language == 'rust' && inputs.macro-contexts }}");
assert.equal(observer[0]['timeout-minutes'],4);
assert.match(observer[0].run,/--profile included-string-payloads/u);
normalized.steps=normalized.steps.filter(step=>step!==observer[0]);
assert.deepEqual(payload(normalized),payload(old),'all previously reviewed producer payload must survive unchanged');
assert.equal(current.if,old.if,'the production admission predicate is unchanged');
const manifest=JSON.parse(fs.readFileSync(file,'utf8')), before=structuredClone(manifest);
const rows=manifest.jobs.filter(row=>row.file==='security.yml'&&row.id==='codeql');assert.equal(rows.length,1);
const hash=job=>createHash('sha256').update(JSON.stringify(payload(job))).digest('hex');
assert.equal(rows[0].payloadSha256,hash(old));
const previous=rows[0].payloadSha256; rows[0].payloadSha256=hash(current);
const reverted=structuredClone(manifest);reverted.jobs.find(row=>row.file==='security.yml'&&row.id==='codeql').payloadSha256=previous;
assert.deepEqual(reverted,before,'only the single reviewed fingerprint may change');
fs.writeFileSync(file,JSON.stringify(manifest,null,2)+'\n');
console.log(JSON.stringify({previous,current:rows[0].payloadSha256,onlyIncludedStringObserverAdded:true,originalProducerPayloadPreserved:true,productionAdmissionUnchanged:true,observerDisabledInProduction:true}));
